prompts.raw:
function ({ vars }) {
  return [
    { role: 'system', content: `{% raw %}${SYSTEM_PROMPT}{% endraw %}` },
    { role: 'user', content: `{% raw %}${vars.request}{% endraw %}` },
  ];
}

